    51|// ─── Session Auth ───────────────────────────────────────────
    52|
    53|async function authenticateSession(
    54|  sql: ReturnType<typeof neon>,
    55|  token: string
    56|): Promise<{ profileId: string; userId: string; name: string } | null> {
    57|  if (!token || token.length < 30) return null;
    58|  try {
    59|    const rows = await sql`
    60|      SELECT id, user_id, name FROM ${sql(SCHEMA)}.profiles
    61|      WHERE session_token = ${token} LIMIT 1
    62|    `;
    63|    if (rows.length === 0) return null;
    64|    return { profileId: rows[0].id, userId: rows[0].user_id || "", name: rows[0].name };
    65|  } catch {
    66|    return null;
    67|  }
    68|}
