   123|// ─── Neon Auth Helpers ─────────────────────────────────────
   124|
   125|/** Call Neon Auth REST API. Returns parsed JSON or throws on error. */
   126|async function callNeonAuth(
   127|  path: string,
   128|  body: Record<string, unknown>
   129|): Promise<NeonAuthResponse> {
   130|  const url = `${NEON_AUTH}${path}`;
   131|  const resp = await fetch(url, {
   132|    method: "POST",
   133|    headers: { "Content-Type": "application/json" },
   134|    body: JSON.stringify(body),
   135|  });
   136|  const data = await resp.json() as Record<string, unknown>;
   137|  if (!resp.ok) {
   138|    const message = (data.message as string) || (data.error as string) || `Auth error (${resp.status})`;
   139|    throw new Error(message);
   140|  }
   141|  return data as unknown as NeonAuthResponse;
   142|}
