   180|// ─── Entrypoint ─────────────────────────────────────────────
   181|
   182|export default {
   183|  async fetch(request: Request, env: Env): Promise<Response> {
   184|    if (request.method === "OPTIONS") return cors(new Response(null, { status: 204 }));
   185|
   186|    const url = new URL(request.url);
   187|    const path = url.pathname;
   188|    const dbUrl = env.DATABASE_URL;
   189|
   190|    if (!dbUrl) {
   191|      return json({ error: "DATABASE_URL not configured" }, 500);
   192|    }
   193|
   194|    try {
   195|      const sql = neon(dbUrl);
   196|
   197|      // ── Schema Init (idempotent) ─────────────────────
   198|      try {
   199|        await sql`CREATE SCHEMA IF NOT EXISTS ${sql(SCHEMA)}`;
   200|      } catch { /* schema may already exist */ }
   201|
   202|      try {
   203|        await sql`
   204|          CREATE TABLE IF NOT EXISTS ${sql(SCHEMA)}.profiles (
   205|            id TEXT PRIMARY KEY,
   206|            user_id TEXT,
   207|            phone TEXT,
   208|            name TEXT NOT NULL DEFAULT '',
   209|            email TEXT,
   210|            session_token TEXT,
   211|            auth_provider TEXT,
   212|            onboarding_complete BOOLEAN DEFAULT false,
   213|            is_logged_in BOOLEAN DEFAULT false,
   214|            dark_theme BOOLEAN DEFAULT false,
   215|            locale_code TEXT DEFAULT 'en',
   216|            family_code TEXT DEFAULT '',
   217|            notifications_enabled BOOLEAN DEFAULT true,
   218|            camp_reminders_enabled BOOLEAN DEFAULT true,
   219|            consent_accepted BOOLEAN DEFAULT false,
   220|            consent_declined BOOLEAN DEFAULT false
   221|          )
   222|        `;
   223|      } catch { /* table may already exist */ }
   224|
   225|      try {
   226|        await sql`
   227|          CREATE TABLE IF NOT EXISTS ${sql(SCHEMA)}.phone_otps (
   228|            phone TEXT PRIMARY KEY,
   229|            otp TEXT NOT NULL,
   230|            expires_at TIMESTAMPTZ NOT NULL,
   231|            attempts INT DEFAULT 0
   232|          )
   233|        `;
   234|      } catch { /* table may already exist */ }
   235|
   236|      // ── Health Check ─────────────────────────────────
   237|      if (path === "/ping") {
   238|        const rows = await sql`SELECT 1 AS ok, NOW() AS now`;
   239|        return json({ ok: true, db: rows[0] });
   240|      }
   241|
   242|      // ═══════════════════════════════════════════════════
   243|      // AUTH ENDPOINTS
   244|      // ═══════════════════════════════════════════════════
   245|
   246|      // ── Email/Password Sign-Up ───────────────────────
   247|      if (path === "/api/auth/signup" && request.method === "POST") {
   248|        try {
   249|          const body: Record<string, unknown> = await request.json();
   250|          const name = (body.name as string)?.trim();
   251|          const email = (body.email as string)?.trim();
   252|          const password = body.password as string;
   253|
   254|          if (!name || !email || !password) {
   255|            return json({ error: "name, email, and password are required" }, 400);
   256|          }
   257|          if (password.length < 8) {
   258|            return json({ error: "Password must be at least 8 characters" }, 400);
   259|          }
   260|
   261|          const neonResp = await callNeonAuth("/sign-up/email", { name, email, password });
   262|          const { profileId, sessionToken } = await upsertProfileFromNeonAuth(
   263|            sql, neonResp.user, "EMAIL"
   264|          );
   265|
   266|          return json({
   267|            token: sessionToken,
   268|            profile: {
   269|              id: profileId,
   270|              user_id: neonResp.user.id,
   271|              name: neonResp.user.name || email.split("@")[0],
   272|              email: neonResp.user.email,
   273|              auth_provider: "EMAIL",
   274|            },
   275|          });
   276|        } catch (e) {
   277|          const message = e instanceof Error ? e.message : String(e);
   278|          return json({ error: message }, 400);
   279|        }
   280|      }
   281|
   282|      // ── Email/Password Sign-In ───────────────────────
   283|      if (path === "/api/auth/signin" && request.method === "POST") {
   284|        try {
   285|          const body: Record<string, unknown> = await request.json();
   286|          const email = (body.email as string)?.trim();
   287|          const password = body.password as string;
   288|
   289|          if (!email || !password) {
   290|            return json({ error: "email and password are required" }, 400);
   291|          }
   292|
   293|          const neonResp = await callNeonAuth("/sign-in/email", { email, password });
   294|          const { profileId, sessionToken } = await upsertProfileFromNeonAuth(
   295|            sql, neonResp.user, "EMAIL"
   296|          );
   297|
   298|          return json({
   299|            token: sessionToken,
   300|            profile: {
   301|              id: profileId,
   302|              user_id: neonResp.user.id,
   303|              name: neonResp.user.name || email.split("@")[0],
   304|              email: neonResp.user.email,
   305|              auth_provider: "EMAIL",
   306|            },
   307|          });
   308|        } catch (e) {
   309|          const message = e instanceof Error ? e.message : String(e);
   310|          return json({ error: message }, 401);
   311|        }
   312|      }
   313|
   314|      // ── Google Sign-In (via Neon Auth social) ────────
   315|      if (path === "/api/auth/google" && request.method === "POST") {
   316|        try {
   317|          const body: Record<string, unknown> = await request.json();
   318|          const idToken = body.id_token as string;
   319|          if (!idToken) return json({ error: "Missing id_token" }, 400);
   320|
   321|          const neonResp = await callNeonAuth("/sign-in/social", {
   322|            provider: "google",
   323|            idToken: { token: idToken },
   324|            callbackURL: "/",
   325|          });
   326|
   327|          const { profileId, sessionToken } = await upsertProfileFromNeonAuth(
   328|            sql, neonResp.user, "GOOGLE"
   329|          );
   330|
   331|          return json({
   332|            token: sessionToken,
   333|            profile: {
   334|              id: profileId,
   335|              user_id: neonResp.user.id,
   336|              name: neonResp.user.name || neonResp.user.email.split("@")[0],
   337|              email: neonResp.user.email,
   338|              auth_provider: "GOOGLE",
   339|            },
   340|          });
   341|        } catch (e) {
   342|          const message = e instanceof Error ? e.message : String(e);
   343|          return json({ error: message }, 401);
   344|        }
   345|      }
   346|
   347|      // ── Phone OTP: Send ──────────────────────────────
   348|      if (path === "/api/auth/phone/send" && request.method === "POST") {
   349|        const body: Record<string, unknown> = await request.json();
   350|        const phone = (body.phone as string)?.trim();
   351|        if (!phone) return json({ error: "Missing phone" }, 400);
   352|
   353|        const otp = generateOtp();
   354|        const expiresAt = new Date(Date.now() + OTP_EXPIRY_MINUTES * 60_000);
   355|
   356|        await sql`
   357|          INSERT INTO ${sql(SCHEMA)}.phone_otps (phone, otp, expires_at, attempts)
   358|          VALUES (${phone}, ${otp}, ${expiresAt.toISOString()}, 0)
   359|          ON CONFLICT (phone) DO UPDATE SET
   360|            otp = EXCLUDED.otp,
   361|            expires_at = EXCLUDED.expires_at,
   362|            attempts = 0
   363|        `;
   364|
   365|        const sent = await sendTwilioSms(
   366|          env, phone,
   367|          `Your VitaHero verification code is: ${otp}`
   368|        );
   369|
   370|        return json({ success: sent, note: sent ? undefined : "OTP generated but SMS delivery may be delayed" });
   371|      }
   372|
   373|      // ── Phone OTP: Verify ────────────────────────────
   374|      if (path === "/api/auth/phone/verify" && request.method === "POST") {
   375|        const body: Record<string, unknown> = await request.json();
   376|        const phone = (body.phone as string)?.trim();
   377|        const otp = (body.otp as string)?.trim();
   378|        if (!phone || !otp) return json({ error: "Missing phone or otp" }, 400);
   379|
   380|        const rows = await sql`
   381|          SELECT otp, expires_at, attempts
   382|          FROM ${sql(SCHEMA)}.phone_otps WHERE phone = ${phone} LIMIT 1
   383|        `;
   384|
   385|        if (rows.length === 0) {
   386|          return json({ error: "No OTP requested for this number" }, 400);
   387|        }
   388|
   389|        const record = rows[0];
   390|        if (record.attempts >= OTP_MAX_ATTEMPTS) {
   391|          return json({ error: "Too many attempts. Request a new OTP." }, 429);
   392|        }
   393|        if (new Date(record.expires_at) < new Date()) {
   394|          return json({ error: "OTP expired. Request a new one." }, 410);
   395|        }
   396|
   397|        // Increment attempts
   398|        await sql`
   399|          UPDATE ${sql(SCHEMA)}.phone_otps
   400|          SET attempts = attempts + 1 WHERE phone = ${phone}
   401|        `;
   402|
   403|        if (record.otp !== otp) {
   404|          return json({ error: "Invalid OTP" }, 401);
   405|        }
   406|
   407|        // OTP verified — clean up
   408|        await sql`DELETE FROM ${sql(SCHEMA)}.phone_otps WHERE phone = ${phone}`;
   409|
   410|        // Create or update profile
   411|        const profileId = `ph_${phone.replace(/\D/g, "").slice(-10)}`;
   412|        const sessionToken = generateToken();
   413|
   414|        const existing = await sql`
   415|          SELECT id FROM ${sql(SCHEMA)}.profiles WHERE id = ${profileId} LIMIT 1
   416|        `;
   417|
   418|        if (existing.length === 0) {
   419|          await sql`
   420|            INSERT INTO ${sql(SCHEMA)}.profiles
   421|              (id, phone, name, session_token, auth_provider,
   422|               onboarding_complete, is_logged_in)
   423|            VALUES (
   424|              ${profileId}, ${phone}, 'Parent', ${sessionToken}, 'PHONE',
   425|              true, true
   426|            )
   427|          `;
   428|        } else {
   429|          await sql`
   430|            UPDATE ${sql(SCHEMA)}.profiles
   431|            SET session_token = ${sessionToken}, is_logged_in = true, phone = ${phone}
   432|            WHERE id = ${profileId}
   433|          `;
   434|        }
   435|
   436|        // Also delete any old OTPs
   437|        try {
   438|          await sql`DELETE FROM ${sql(SCHEMA)}.phone_otps WHERE expires_at < NOW()`;
   439|        } catch { /* best effort */ }
   440|
   441|        return json({
   442|          token: sessionToken,
   443|          profile: {
   444|            id: profileId,
   445|            phone,
   446|            name: "Parent",
   447|            auth_provider: "PHONE",
   448|          },
   449|        });
   450|      }
   451|
   452|      // ── Verify Session Token ─────────────────────────
   453|      if (path === "/api/auth/me" && request.method === "GET") {
   454|        const token = extractToken(request);
   455|        const session = await authenticateSession(sql, token);
   456|        if (!session) return json({ error: "Invalid or expired session" }, 401);
   457|
   458|        const profile = await sql`
   459|          SELECT * FROM ${sql(SCHEMA)}.profiles WHERE id = ${session.profileId} LIMIT 1
   460|        `;
   461|        return json(profile[0] || null);
   462|      }
   463|
   464|      // ── Logout ───────────────────────────────────────
   465|      if (path === "/api/auth/logout" && request.method === "POST") {
   466|        const token = extractToken(request);
   467|        if (token) {
   468|          await sql`
   469|            UPDATE ${sql(SCHEMA)}.profiles
   470|            SET session_token = NULL, is_logged_in = false
   471|            WHERE session_token = ${token}
   472|          `;
   473|        }
   474|        return json({ success: true });
   475|      }
   476|
   477|      // ═══════════════════════════════════════════════════
   478|      // AUTHENTICATED DATA ENDPOINTS
   479|      // ═══════════════════════════════════════════════════
   480|
   481|      const token = extractToken(request);
   482|      const session = await authenticateSession(sql, token);
   483|
   484|      // ═══════════════════════════════════════════════════
   485|      // Profiles
