   524|          )
   525|          ON CONFLICT (id) DO UPDATE SET
   526|            user_id = EXCLUDED.user_id, phone = EXCLUDED.phone,
   527|            name = EXCLUDED.name, email = EXCLUDED.email,
   528|            onboarding_complete = EXCLUDED.onboarding_complete,
   529|            is_logged_in = EXCLUDED.is_logged_in,
   530|            dark_theme = EXCLUDED.dark_theme,
   531|            locale_code = EXCLUDED.locale_code,
